import { SITE_URL } from "@/config/constants";
import { listSitemapIds } from "@/lib/sitemap-layout";

// Sitemap index (/sitemap-index.xml): the single URL to submit to search engines.
// It can't live at /sitemap.xml: app/sitemap.ts owns that route. It lists every
// chunk generated by app/sitemap.ts (/sitemap/{id}.xml).
export const revalidate = 21600; // 6h, same as REVALIDATE_SECONDS (must be a literal)

export async function GET() {
  const ids = await listSitemapIds();
  const lastmod = new Date().toISOString();
  const entries = ids
    .map(
      (id) =>
        `<sitemap><loc>${SITE_URL}/sitemap/${id}.xml</loc><lastmod>${lastmod}</lastmod></sitemap>`
    )
    .join("\n");

  return new Response(
    `<?xml version="1.0" encoding="UTF-8"?>\n<sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${entries}\n</sitemapindex>\n`,
    { headers: { "Content-Type": "application/xml; charset=utf-8" } }
  );
}
